def nav_icon(key):
    paths={
        'analyzer':'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
        'sbom-to-cve':'M4 4h10v16H4z M8 8h3 M8 12h3 M16 8l5 4-5 4 M14 12h7',
        'vex-decision':'M12 3l8 4v5c0 5-8 9-8 9S4 17 4 12V7z M8 12l3 3 5-6',
        'dataset':'M4 5c0-3 16-3 16 0v14c0 3-16 3-16 0z M4 5c0 3 16 3 16 0 M4 12c0 3 16 3 16 0',
        'ics-sbom':'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6',
        'source':'M12 3l9 17H3z M12 9v5 M12 17v1',
        'published-vex':'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4'}
    path=paths.get(key,paths['ics-sbom'])
    return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+path+'"/></svg>'
